const script = `
$ProgressPreference='SilentlyContinue'
$h=@{'User-Agent'='dsh-check';'Accept'='application/vnd.github+json'}
try {
  $r = Invoke-RestMethod -Uri 'https://api.github.com/repos/Ebony-Vinyl/dsh-our-free-model/releases?per_page=8' -Headers $h -TimeoutSec 30
  foreach ($x in $r) { "### $($x.tag_name)  $($x.published_at)  dl:$($x.assets.Count)" }
} catch { "ERR $($_.Exception.Message)" }
"---- forks ----"
try {
  $f = Invoke-RestMethod -Uri 'https://api.github.com/repos/Ebony-Vinyl/dsh-our-free-model/forks?sort=stargazers&per_page=10' -Headers $h -TimeoutSec 30
  foreach ($x in $f) { "$($x.stargazers_count)|$($x.full_name)|$($x.pushed_at)" }
} catch { "ERR $($_.Exception.Message)" }
`;
const r = await tools.pwsh({ command: script, description: "Fetch releases and forks" });
console.log(r.kind === "foreground" ? r.stdout.text + r.stderr.text : JSON.stringify(r).slice(0,300));

async function s(q: string[]) { for (let i=0;i<4;i++){ try { return await tools.web_search({ queries: q }); } catch(e){ await new Promise(r=>setTimeout(r,2000)); } } return {error:"failed"}; }
const rev = await s(["our-free-model 插件 用户 评价 好用吗", "DSH 免费模型 插件 our-free-model workbuddy opencode2dsh 对比"]);
console.log("SEARCH:", JSON.stringify(rev).slice(0, 3000));
